"use client"

import type { ArtDef } from "@/lib/ink/art/types"
import { drawSkeleton, memo } from "@/lib/ink/art-draw"
import { useEnsureInkDefs } from "@/lib/ink/react"
import { cn } from "@/lib/utils"

const MARKS = {
  apple: {
    grid: 24,
    parts: [
      ["s", "M12 8.2 C10.6 7.1 7.5 7.4 6.5 10.3 C5.6 13 6.8 16.6 8.4 18.7 C9.4 20 10.7 19.5 12 19 C13.3 19.5 14.6 20.2 15.7 18.8 C17.3 16.8 18.1 15.3 18.3 14.5 C16.3 13.6 15.9 10.7 17.8 9.3 C16.4 7.3 13.6 7 12 8.2", 1.05],
      ["s", "M12.1 7.8 C12 6.1 13.1 4.7 14.9 4.3", 1],
    ],
  },
  google: {
    grid: 24,
    parts: [
      ["s", "M20.3 8.6 C18.8 5.2 15.4 3.5 12 3.9 C7.6 4.4 4.2 8.2 4.3 12.6 C4.4 17.2 7.9 20.6 12 20.5 C16.3 20.4 19.8 17.4 20 12.4", 1.15],
      ["s", "M12.2 12.5 L20.1 12.4", 1.1],
    ],
  },
} satisfies Record<string, ArtDef>

type BrandMarkName = keyof typeof MARKS

function BrandMark({ name, size = 16, className }: { name: BrandMarkName; size?: number; className?: string }) {
  useEnsureInkDefs()
  const res = memo(`auth-brand|${name}|${size}`, () => drawSkeleton(MARKS[name], size, name, { tone: "ui", kind: "icon", nib: 1.6 }))
  return (
    <svg
      data-ink="icon"
      aria-hidden="true"
      focusable="false"
      viewBox={`0 0 ${res.w} ${res.h}`}
      width={size}
      height={size}
      className={cn("pointer-events-none shrink-0 overflow-visible", className)}
      dangerouslySetInnerHTML={{ __html: res.svg }}
    />
  )
}

export { BrandMark }
export type { BrandMarkName }

"use client"

import * as React from "react"
import { zodResolver } from "@hookform/resolvers/zod"
import { useForm } from "react-hook-form"
import { z } from "zod"

import { BrandMark } from "@/components/blocks/signup-05/components/signup-05-brand-marks"
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Button } from "@/components/ui/button"
import { Circled } from "@/components/ui/circled"
import { Field, FieldDescription, FieldError, FieldGroup, FieldLabel, FieldSeparator } from "@/components/ui/field"
import { Icon } from "@/components/ui/icon"
import { Input } from "@/components/ui/input"
import { Mascot } from "@/components/ui/mascot"
import { Spinner } from "@/components/ui/spinner"
import { cn } from "@/lib/utils"

const schema = z.object({
  email: z.email("Enter a full address, like ada@notes.dev."),
})

type SignupValues = z.infer<typeof schema>

type SignupFormProps = Omit<React.ComponentProps<"div">, "onSubmit"> & {
  onSubmit?: (values: SignupValues) => void | Promise<void>
}

const pretend = () => new Promise<void>((resolve) => setTimeout(resolve, 700))

function SignupForm({ className, onSubmit, ...props }: SignupFormProps) {
  const uid = React.useId()
  const id = (name: string) => `${uid}-${name}`
  const [formError, setFormError] = React.useState<string | null>(null)
  const [sentTo, setSentTo] = React.useState<string | null>(null)
  const {
    register,
    handleSubmit,
    reset,
    setFocus,
    formState: { errors, isSubmitting },
  } = useForm<SignupValues>({ resolver: zodResolver(schema), mode: "onTouched", defaultValues: { email: "" } })

  const sentRef = React.useRef<HTMLDivElement>(null)
  React.useEffect(() => {
    if (sentTo) sentRef.current?.focus()
  }, [sentTo])

  const refocus = React.useRef(false)
  React.useEffect(() => {
    if (sentTo === null && refocus.current) {
      refocus.current = false
      setFocus("email")
    }
  }, [sentTo, setFocus])

  const submit = handleSubmit(async (values) => {
    setFormError(null)
    try {
      await (onSubmit ?? pretend)(values)
      setSentTo(values.email)
    } catch (error) {
      setFormError(error instanceof Error && error.message ? error.message : "We could not send that link. Try again in a moment.")
    }
  })

  return (
    <div className={cn("@container/signup flex flex-col gap-6", className)} {...props}>
      <form onSubmit={submit} noValidate>
        <FieldGroup>
          <div className="flex flex-col items-center gap-2 text-center">
            <Mascot pose={sentTo ? "celebrate" : "think"} size={88} />
            <h1 className="my-3 font-script text-[2.25rem] leading-none font-bold">
              Pull up a <Circled tone="marker" className="mx-2">chair</Circled>
            </h1>
            <FieldDescription>
              Already have an account? <a href="#login">Sign in</a>
            </FieldDescription>
          </div>
          {formError ? (
            <Alert variant="destructive">
              <Icon name="circle-alert" />
              <AlertTitle>That did not go through</AlertTitle>
              <AlertDescription>{formError}</AlertDescription>
            </Alert>
          ) : null}
          {sentTo ? (
            <>
              <Alert ref={sentRef} tabIndex={-1} variant="success" role="status" className="outline-none">
                <Icon name="mail-check" />
                <AlertTitle>Check your inbox</AlertTitle>
                <AlertDescription>
                  A link is on its way to {sentTo}. Open it on this device to finish.
                  {onSubmit ? null : " (This is a demo: nothing was sent.)"}
                </AlertDescription>
              </Alert>
              <Field>
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => {
                    refocus.current = true
                    setSentTo(null)
                    reset({ email: sentTo })
                  }}
                >
                  Use a different email
                </Button>
              </Field>
            </>
          ) : (
            <>
              <Field data-invalid={!!errors.email}>
                <FieldLabel htmlFor={id("email")}>Email</FieldLabel>
                <Input
                  id={id("email")}
                  type="email"
                  autoComplete="email"
                  placeholder="ada@notes.dev"
                  required
                  aria-invalid={!!errors.email}
                  aria-describedby={errors.email ? id("email-error") : undefined}
                  {...register("email")}
                />
                <FieldError id={id("email-error")} errors={[errors.email]} />
              </Field>
              <Field>
                <Button type="submit" aria-busy={isSubmitting} disabled={isSubmitting}>
                  {isSubmitting ? (
                    <>
                      <Spinner aria-hidden="true" /> Sending
                    </>
                  ) : (
                    "Email me a link to start"
                  )}
                </Button>
              </Field>
            </>
          )}
          <FieldSeparator>Or continue with</FieldSeparator>
          <Field className="grid gap-4 @sm/signup:grid-cols-2">
            <Button variant="outline" type="button" aria-label="Continue with Apple">
              <BrandMark name="apple" />
              Apple
            </Button>
            <Button variant="outline" type="button" aria-label="Continue with Google">
              <BrandMark name="google" />
              Google
            </Button>
          </Field>
        </FieldGroup>
      </form>
      <FieldDescription className="px-6 text-center text-balance [&>a]:whitespace-nowrap">
        By continuing you agree to our <a href="#terms">Terms of Service</a> and <a href="#privacy">Privacy Policy</a>.
      </FieldDescription>
    </div>
  )
}

export { SignupForm }
export type { SignupFormProps, SignupValues }
